import heapq

def solve(stones):
    heap = []
    for value in stones:
        heap.append(-value)
    heapq.heapify(heap)
    while len(heap) > 1:
        first = -heapq.heappop(heap)
        second = -heapq.heappop(heap)
        if first != second:
            heapq.heappush(heap, -(first - second))
    if len(heap) == 0:
        return 0
    return -heap[0]

